package ktanesolver.module.modded.regular.instructions;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.enums.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.instructions.InstructionsInput.*;
class InstructionsSolverTest{private final InstructionsSolver solver=new InstructionsSolver();private static final List<Button>BUTTONS=List.of(new Button(ButtonColor.RED,"A"),new Button(ButtonColor.GREEN,"B"),new Button(ButtonColor.YELLOW,"C"),new Button(ButtonColor.BLUE,"D"));
	@Test void appliesAllSixRulesInSourceOrder(){BombEntity empty=bomb(0,0);assertRule(empty,input(Edgework.PORTS,ButtonReference.FOURTH,Edgework.BATTERIES,ButtonReference.SECOND,ButtonReference.FIRST,0),1,4);BombEntity b=bomb(5,4);assertRule(b,input(Edgework.TWO_FACTORS,ButtonReference.THIRD,Edgework.BATTERIES,ButtonReference.FIRST,ButtonReference.SECOND,1),2,3);assertRule(b,input(Edgework.BATTERIES,ButtonReference.FIRST,Edgework.TWO_FACTORS,ButtonReference.SECOND,ButtonReference.THIRD,1),3,3);assertRule(b,input(Edgework.BATTERIES,ButtonReference.SECOND,Edgework.INDICATORS,ButtonReference.FIRST,ButtonReference.THIRD,1),4,2);BombEntity onePort=bomb(0,0);onePort.replacePortPlates(List.of(Set.of(PortType.DVI)));assertRule(onePort,input(Edgework.PORTS,ButtonReference.THIRD,Edgework.TWO_FACTORS,ButtonReference.FIRST,ButtonReference.SECOND,1),5,4);assertRule(onePort,input(Edgework.PORTS,ButtonReference.SECOND,Edgework.TWO_FACTORS,ButtonReference.SECOND,ButtonReference.THIRD,1),6,2);}
	@Test void resolvesEveryEdgeworkScreenValue(){BombEntity b=bomb(3,3);b.setAaBatteryCount(2);b.setDBatteryCount(1);b.setIndicators(new LinkedHashMap<>(Map.of("CAR",true,"FRK",false,"BOB",false)));b.replacePortPlates(List.of(Set.of(PortType.DVI,PortType.SERIAL),Set.of(PortType.DVI)));b.setStrikes(2);b.getModules().get(0).setSolved(true);int[]expected={3,2,3,1,2,3,2,3,3,3,7,1,2,2};for(int i=0;i<Edgework.values().length;i++)assertThat(InstructionsSolver.edgework(b,Edgework.values()[i],7)).as(Edgework.values()[i].name()).isEqualTo(expected[i]);}
	@Test void mapsColorsLabelsAndOrdinalsToPositions(){assertThat(InstructionsSolver.position(ButtonReference.BLUE,BUTTONS)).isEqualTo(3);assertThat(InstructionsSolver.position(ButtonReference.B,BUTTONS)).isEqualTo(1);assertThat(InstructionsSolver.position(ButtonReference.THIRD,BUTTONS)).isEqualTo(2);}
	@Test void validatesUniqueButtons(){List<Button>bad=List.of(BUTTONS.get(0),BUTTONS.get(0),BUTTONS.get(2),BUTTONS.get(3));assertThat(solver.solve(new RoundEntity(),bomb(0,0),new ModuleEntity(),new InstructionsInput(Edgework.BATTERIES,ButtonReference.RED,Edgework.PORTS,ButtonReference.GREEN,ButtonReference.BLUE,bad,0))).isInstanceOf(SolveFailure.class);}
	private InstructionsInput input(Edgework s1,ButtonReference s2,Edgework s3,ButtonReference s4,ButtonReference s5,int tf){return new InstructionsInput(s1,s2,s3,s4,s5,BUTTONS,tf);}@SuppressWarnings("unchecked")private void assertRule(BombEntity b,InstructionsInput i,int rule,int position){InstructionsOutput out=((SolveSuccess<InstructionsOutput>)solver.solve(new RoundEntity(),b,new ModuleEntity(),i)).output();assertThat(out.rule()).isEqualTo(rule);assertThat(out.position()).isEqualTo(position);}private static BombEntity bomb(int batteries,int indicators){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");b.setAaBatteryCount(batteries);Map<String,Boolean>map=new LinkedHashMap<>();for(int i=0;i<indicators;i++)map.put("I"+i,i%2==0);b.setIndicators(map);List<ModuleEntity>modules=new ArrayList<>();for(int i=0;i<3;i++)modules.add(new ModuleEntity());b.setModules(modules);return b;}}
